export function getCHRISTIAN_LIVING_CURRICULUMLevel(levelNumber: number): CurriculumLevelData {
  const safeLevel = Math.max(1, Math.min(100, levelNumber));
  return CHRISTIAN_LIVING_CURRICULUM_LEVELS[safeLevel - 1];
}
